import React, { useState } from "react";

export function ToggleSwitch() {
  const [checked, setChecked] = useState(true);
  return (
    <button role="switch" aria-checked={checked} onClick={() => setChecked(!checked)} className={`w-11 h-6 rounded-full p-0.5 border transition-colors ${checked ? "bg-primary border-primary" : "bg-muted border-border"}`}>
      <span className={`w-5 h-5 rounded-full block transition-transform ${checked ? "bg-primary-foreground translate-x-5" : "bg-muted-foreground/60 translate-x-0"}`} />
    </button>
  );
}
